use Scalar::Util ();

# --- METRICS ---
# line_count: 14
# cyclomatic_complexity: 1
# max_nesting_depth: 5

# --- HINTS ---
# method_chain: need: $self->{file_spec_class}
# method_chain: need: $self->_spec_class
# method_chain: need: $self->SUPER::new
# method_chain: need: $foreign->{volume}
# method_chain: need: $self->{volume}
# method_chain: need: $self->_spec
# method_chain: need: $foreign->_spec
# method_chain: need: $foreign->{dirs}
# method_chain: need: $self->{dirs}
# --- FUNCTION: as_foreign ---
sub as_foreign {
  my ($self, $type) = @_;

  my $foreign = do {
    local $self->{file_spec_class} = $self->_spec_class($type);
    $self->SUPER::new;
  };

  # Clone internal structure
  $foreign->{volume} = $self->{volume};
  my ($u, $fu) = ($self->_spec->updir, $foreign->_spec->updir);
  $foreign->{dirs} = [ map {$_ eq $u ? $fu : $_} @{$self->{dirs}}];
  return $foreign;
}

